import javax.measure.Quantity;
import javax.measure.quantity.Length;
import tech.units.indriya.quantity.Quantities;
import static javax.measure.MetricPrefix.KILO;
import static tech.units.indriya.unit.Units.METRE;

Quantity<Length> span  = Quantities.getQuantity(3, KILO(METRE));
Quantity<Length> gap   = Quantities.getQuantity(500, METRE);
Quantity<Length> total = span.add(gap).to(METRE);      // 3500 m
Quantity<Length> miles = total.to(Units.MILE);         // compatible only

public record Quantity(double amount, LengthUnit unit) {
    public Quantity {                              // compact constructor: normalise
        amount = amount * unit.toMetres;
        unit = LengthUnit.METRE;
    }
    public Quantity plus(Quantity other) { return new Quantity(amount + other.amount, unit); }
    public double in(LengthUnit target) { return amount / target.toMetres; }
}
